-- v41 live test for conservative boost refunds (migration 20261027000009). Run as the project owner (SQL editor / MCP execute_sql).
-- Creates throwaway users inside ONE transaction and ends with RAISE EXCEPTION 'V41RESULT pass=N fail=M ...', so everything rolls back.
-- Generated by the v41 build (one check per line). Covers: expiry/block/recipient-deleted paths, idempotency, spend-bound, read never
-- refunded, daily cap -> held -> support release, support refund, append-only audit, owner view, ACLs, mesh ledger + caps.
do $t$
declare
  a uuid := gen_random_uuid(); b uuid := gen_random_uuid(); c uuid := gen_random_uuid(); d uuid := gen_random_uuid(); e uuid := gen_random_uuid();
  cab uuid; cac uuid; ced uuid; m1 uuid; m2 uuid; m3 uuid; m4 uuid; m5 uuid; m6 uuid; m7 uuid; mm uuid; ids uuid[] := '{}'; hl bigint;
  x bigint; n int; i int; s text; r jsonb; out text := ''; pass int := 0; fail int := 0; ok boolean;
begin
  insert into auth.users (id, instance_id, aud, role, email, created_at, updated_at) select u, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'v41-' || u || '@test.invalid', now(), now() from unnest(array[a, b, c, d, e]) u;
  insert into public.profiles (id, handle, age_band) select u, 'v41_' || substr(md5(u::text),1,10), 'adult' from unnest(array[a, b, c, d, e]) u on conflict (id) do update set age_band = 'adult';
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.conversations (user_a, user_b, created_by) values (least(a,b), greatest(a,b), a) returning id into cab;
  perform set_config('request.jwt.claims', '', true);
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.conversations (user_a, user_b, created_by) values (least(a,c), greatest(a,c), a) returning id into cac;
  perform set_config('request.jwt.claims', '', true);
  perform set_config('request.jwt.claims', json_build_object('sub', e, 'role', 'authenticated')::text, true);
  insert into public.conversations (user_a, user_b, created_by) values (least(e,d), greatest(e,d), e) returning id into ced;
  perform set_config('request.jwt.claims', '', true);
  insert into public.boost_ledger (user_id, delta, reason) values (a, 30, 'grant'), (e, 3, 'grant');
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 ct', true) returning id into m1;
  perform set_config('request.jwt.claims', '', true);
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = 29), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'spend recorded (balance 30 -> 29)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  update public.messages set expires_at = now() - interval '1 minute' where id = m1;
  perform app.purge_expired();
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = 30), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'expired unread boost refunded by purge (29 -> 30)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = m1 and outcome = 'refunded' and cause = 'expired' and actor = 'cron') = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'audit row (expired/cron/refunded)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce((not exists (select 1 from public.messages where id = m1)), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'expired message purged' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform app.purge_expired(); s := app.boost_refund_decide(m1, 'expired');
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = 30 and s = 'duplicate'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'idempotent: 2nd purge + direct retry no extra credit (duplicate)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from public.boost_ledger where message_id = m1 and reason = 'refund') = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'exactly one refund row per message' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 ct', true) returning id into m2;
  perform set_config('request.jwt.claims', '', true);
  update public.messages set status = 'read', expires_at = now() - interval '1 minute' where id = m2;
  s := app.boost_refund_decide(m2, 'expired');
  ok := coalesce((s = 'denied_read'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'read message never refunded (denied_read)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = m2 and outcome = 'denied_read') = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'denial audited' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 ct', true) returning id into m3;
  perform set_config('request.jwt.claims', '', true);
  s := app.boost_refund_decide(m3, 'expired');
  ok := coalesce((s = 'denied_not_eligible'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'not expired yet -> denied_not_eligible' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := app.boost_refund_decide(m3, 'blocked');
  ok := coalesce((s = 'denied_not_eligible'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || '''blocked'' without a block -> denied' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := app.boost_refund_decide(m3, 'admin');
  ok := coalesce((s = 'denied_not_eligible'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || '''admin'' cause outside service path -> denied' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  x := (select coalesce(sum(delta),0) from public.boost_ledger where user_id = a);
  perform set_config('request.jwt.claims', json_build_object('sub', b, 'role', 'authenticated')::text, true);
  set local role authenticated; insert into public.blocks (blocker_id, blocked_id) values (b, a); reset role;
  perform set_config('request.jwt.claims', '', true);
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x + 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'recipient blocks sender -> unread boost refunded' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select not boosted from public.messages where id = m3)), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'refunded message un-pinned (boosted=false)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = m3 and cause = 'blocked' and outcome = 'refunded' and actor = 'trigger') = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'audit row (blocked/trigger)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  delete from public.blocks where blocker_id = b and blocked_id = a; insert into public.blocks (blocker_id, blocked_id) values (b, a); s := app.boost_refund_decide(m3, 'blocked');
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x + 1 and s = 'duplicate'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'unblock + re-block: no second refund' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  delete from public.blocks where blocker_id = b and blocked_id = a;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 plain', false) returning id into m4;
  perform set_config('request.jwt.claims', '', true);
  s := app.boost_refund_decide(m4, 'admin', 'service', 'x');
  ok := coalesce((s = 'denied_no_spend'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'unboosted message (no spend row) -> denied_no_spend even for support' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := app.boost_refund_decide(gen_random_uuid(), 'expired');
  ok := coalesce((s = 'denied_unknown'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'unknown message -> denied_unknown' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  begin perform app.boost_refund_decide(m4, 'bogus'); out := out || 'FAIL bad cause rejected; '; fail := fail + 1; exception when invalid_parameter_value then out := out || 'PASS bad cause rejected; '; pass := pass + 1; end;
  x := (select coalesce(sum(delta),0) from public.boost_ledger where user_id = a);
  for i in 1..10 loop perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true); insert into public.messages (conversation_id, sender_id, body, boosted) values (cac, a, 'v41 cap', true) returning id into mm; ids := ids || mm; end loop;
  perform set_config('request.jwt.claims', '', true);
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x - 10), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || '10 boosts spent' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  update public.messages set expires_at = now() - interval '1 minute' where id = any(ids); perform app.purge_expired();
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x - 2), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'cap: only 8 more refunded (10/24 h total)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = any(ids) and outcome = 'held') = 2), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'cap: 2 refunds HELD for review' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from public.boost_ledger where user_id = a and reason = 'refund' and created_at > now() - interval '24 hours') = app.boost_refund_daily_cap()), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'refunds in 24 h = cap exactly' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  select id into hl from app.boost_refund_log where message_id = any(ids) and outcome = 'held' order by id limit 1;
  begin update app.boost_refund_log set outcome = 'refunded' where id = hl; out := out || 'FAIL audit log UPDATE blocked; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS audit log UPDATE blocked; '; pass := pass + 1; end;
  begin delete from app.boost_refund_log where id = hl; out := out || 'FAIL audit log DELETE blocked; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS audit log DELETE blocked; '; pass := pass + 1; end;
  set local role service_role;
  s := public.boost_refund_release(hl, 'v41 test release');
  ok := coalesce((s = 'released'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'service role releases a held refund' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := public.boost_refund_release(hl);
  ok := coalesce((s = 'duplicate'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'release twice -> duplicate' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := public.boost_refund_release(-1);
  ok := coalesce((s = 'not_held'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'release of non-held row -> not_held' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  reset role;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 rd', true) returning id into m7;
  perform set_config('request.jwt.claims', '', true);
  update public.messages set status = 'read' where id = m7; x := x - 1; set local role service_role;
  s := public.boost_refund_admin(m7, 'support check');
  ok := coalesce((s = 'denied_read'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'support refund of a READ message denied' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  s := public.boost_refund_admin(m2, 'support check');
  ok := coalesce((s = 'denied_not_eligible'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'support refund of a purged message denied (read state unknown)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  begin perform public.boost_refund_admin(m2, ''); out := out || 'FAIL support refund needs a note; '; fail := fail + 1; exception when invalid_parameter_value then out := out || 'PASS support refund needs a note; '; pass := pass + 1; end;
  begin perform count(*) from app.boost_refund_log; out := out || 'FAIL service role has no direct audit table access; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS service role has no direct audit table access; '; pass := pass + 1; end;
  reset role;
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x - 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'balance after release' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (cab, a, 'v41 adm', true) returning id into m5;
  perform set_config('request.jwt.claims', '', true);
  set local role service_role; s := public.boost_refund_admin(m5, 'support: outage goodwill'); reset role;
  ok := coalesce((s = 'refunded' and (select coalesce(sum(delta),0) from public.boost_ledger where user_id = a) = x - 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'support refund bypasses daily cap (spend-bound)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = m5 and cause = 'admin' and actor = 'service' and note like 'support%') = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'support refund audited with note' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', e, 'role', 'authenticated')::text, true);
  insert into public.messages (conversation_id, sender_id, body, boosted) values (ced, e, 'v41 ct', true) returning id into m6;
  perform set_config('request.jwt.claims', '', true);
  x := (select coalesce(sum(delta),0) from public.boost_ledger where user_id = e);
  delete from auth.users where id = d;
  ok := coalesce(((select coalesce(sum(delta),0) from public.boost_ledger where user_id = e) = x + 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'recipient deletes account -> sender refunded before cascade' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from app.boost_refund_log where message_id = m6 and cause = 'recipient_deleted' and outcome = 'refunded' and recipient_id is null) = 1), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'audit keeps no deleted-recipient id' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce((not exists (select 1 from public.messages where id = m6)), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'messages still cascade-deleted' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  perform set_config('request.jwt.claims', json_build_object('sub', a, 'role', 'authenticated')::text, true);
  set local role authenticated;
  select count(*) into n from public.my_boost_refunds(200);
  ok := coalesce((n >= 12), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'sender sees own refund decisions' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  begin perform count(*) from app.boost_refund_log; out := out || 'FAIL client cannot read audit table; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot read audit table; '; pass := pass + 1; end;
  begin perform app.boost_refund_decide(m3, 'admin', 'service', 'x'); out := out || 'FAIL client cannot call decide; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot call decide; '; pass := pass + 1; end;
  begin perform public.boost_refund_admin(m3, 'self refund'); out := out || 'FAIL client cannot call support refund; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot call support refund; '; pass := pass + 1; end;
  begin perform public.boost_refund_release(hl); out := out || 'FAIL client cannot release held; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot release held; '; pass := pass + 1; end;
  begin perform public.mesh_refund('register', 'abcdefgh', 'fromhash01', 'tohash0001'); out := out || 'FAIL client cannot call mesh_refund; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot call mesh_refund; '; pass := pass + 1; end;
  begin insert into public.boost_ledger (user_id, delta, reason, message_id) values (a, 1, 'refund', gen_random_uuid()); out := out || 'FAIL client cannot write ledger; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS client cannot write ledger; '; pass := pass + 1; end;
  reset role;
  perform set_config('request.jwt.claims', json_build_object('sub', b, 'role', 'authenticated')::text, true);
  set local role authenticated;
  select count(*) into n from public.my_boost_refunds(200);
  ok := coalesce((n = 0), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'other user sees none of the sender''s refunds' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  reset role;
  perform set_config('request.jwt.claims', '', true);
  set local role anon;
  begin perform * from public.my_boost_refunds(5); out := out || 'FAIL anon denied my_boost_refunds; '; fail := fail + 1; exception when insufficient_privilege then out := out || 'PASS anon denied my_boost_refunds; '; pass := pass + 1; end;
  reset role;
  set local role service_role;
  r := public.mesh_refund('register', 'v41msg01', 'fromhash01', 'tohash0001');
  ok := coalesce(((r->>'ok')::boolean), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh register' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('register', 'v41msg01', 'fromhash01', 'tohash0001');
  ok := coalesce((r->>'reason' = 'dup'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh register dup refused' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('claim', 'v41msg01', 'fromhash01');
  ok := coalesce((r->>'reason' = 'too early'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh claim too early' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('claim', 'v41msg01', 'otherhash1');
  ok := coalesce((r->>'reason' = 'unknown'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh claim by someone else -> unknown' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('register', 'v41msg02', 'fromhash01', 'tohash0001'); r := public.mesh_refund('receipt', 'v41msg02', 'fromhash01', 'tohash0001');
  ok := coalesce(((r->>'ok')::boolean), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh receipt recorded' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('receipt', 'v41msg01', 'fromhash01', 'wrongto001');
  ok := coalesce((r->>'reason' = 'unknown'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh receipt from wrong recipient ignored' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('register', 'bad id!', 'fromhash01', 'tohash0001');
  ok := coalesce((r->>'reason' = 'bad request'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh bad msg id refused' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('register', 'v41msg03', 'fromhash01', 'fromhash01');
  ok := coalesce((r->>'reason' = 'bad request'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh self-addressed refused' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  reset role; update app.mesh_boost_refunds set registered_at = now() - interval '1 minute' where from_h = 'fromhash01'; set local role service_role;
  r := public.mesh_refund('claim', 'v41msg02', 'fromhash01');
  ok := coalesce((r->>'reason' = 'delivered'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh delivered (signed receipt) -> no refund' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('claim', 'v41msg01', 'fromhash01');
  ok := coalesce(((r->>'refunded')::boolean), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh no receipt after timeout -> refund' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  r := public.mesh_refund('claim', 'v41msg01', 'fromhash01');
  ok := coalesce(((r->>'already')::boolean), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh claim idempotent (already)' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  for i in 1..12 loop perform public.mesh_refund('register', 'v41cap' || lpad(i::text, 3, '0'), 'fromhash01', 'tohash0001'); end loop;
  reset role; update app.mesh_boost_refunds set registered_at = now() - interval '1 minute' where from_h = 'fromhash01'; set local role service_role;
  n := 0; for i in 1..12 loop r := public.mesh_refund('claim', 'v41cap' || lpad(i::text, 3, '0'), 'fromhash01'); if (r->>'refunded')::boolean then n := n + 1; end if; s := r->>'reason'; end loop;
  ok := coalesce((n = 9 and s = 'capped'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh cap: 10 refunds / 24 h per sender, rest capped' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  reset role;
  insert into app.mesh_boost_refunds (msg_id, from_h, to_h, registered_at) select 'v41reg' || g, 'fromhash02', 'tohash0001', now() - interval '1 hour' from generate_series(1, 300) g;
  set local role service_role; r := public.mesh_refund('register', 'v41over1', 'fromhash02', 'tohash0001'); reset role;
  ok := coalesce((r->>'reason' = 'register cap'), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'mesh register cap 300 / 24 h' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  insert into app.mesh_boost_refunds (msg_id, from_h, to_h, registered_at) values ('v41old01', 'fromhash03', 'tohash0001', now() - interval '9 days'); perform app.purge_expired();
  ok := coalesce((not exists (select 1 from app.mesh_boost_refunds where msg_id = 'v41old01')), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'purge drops mesh rows older than 8 days' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
  ok := coalesce(((select count(*) from pg_class c join pg_namespace s on s.oid = c.relnamespace where s.nspname = 'app' and c.relname in ('boost_refund_log','mesh_boost_refunds') and c.relrowsecurity) = 2), false); out := out || case when ok then 'PASS ' else 'FAIL ' end || 'RLS on both new tables' || '; '; if ok then pass := pass + 1; else fail := fail + 1; end if;
